1. package securitykey
2. 
3. import (
4. 	"bytes"
5. 	"crypto"
6. 	"crypto/ecdsa"
7. 	"fmt"
8. 	"strings"
9. 	"time"
10. 
11. 	"github.com/go-piv/piv-go/piv"
12. 	"golang.org/x/crypto/openpgp"
13. 	"golang.org/x/crypto/openpgp/armor"
14. 	"golang.org/x/crypto/openpgp/errors"
15. 	"golang.org/x/crypto/openpgp/packet"
16. 	"golang.org/x/crypto/ssh"
17. )
18. 
19. var touchStringMap = map[piv.TouchPolicy]string{
20. 	piv.TouchPolicyNever:  "never",
21. 	piv.TouchPolicyAlways: "always",
22. 	piv.TouchPolicyCached: "cached",
23. }
24. 
25. // Entity wraps a synthesized openpgp.Entity and associates it with a
26. // SigningKey.
27. type Entity struct {
28. 	openpgp.Entity
29. 	CryptoKey
30. }
31. 
32. // Comment returns a comment suitable for e.g. the SSH public key format
33. func (k *SecurityKey) Comment(ss *SlotSpec) string {
34. 	return fmt.Sprintf("%v #%v, touch policy: %s", k.card, k.serial,
35. 		touchStringMap[ss.TouchPolicy])
36. }
37. 
38. // StringsSSH returns an array of commonly formatted SSH keys as strings.
39. func (k *SecurityKey) StringsSSH() []string {
40. 	var ss []string
41. 	for _, s := range k.SigningKeys() {
42. 		ss = append(ss, fmt.Sprintf("%s %s\n",
43. 			strings.TrimSuffix(string(ssh.MarshalAuthorizedKey(s.PubSSH)), "\n"),
44. 			k.Comment(&s.SlotSpec)))
45. 	}
46. 	return ss
47. }
48. 
49. func (k *SecurityKey) synthesizeEntity(ck *CryptoKey, now time.Time,
50. 	name, email, comment string) (*openpgp.Entity, error) {
51. 	cryptoPrivKey, err := k.PrivateKey(ck)
52. 	if err != nil {
53. 		return nil, fmt.Errorf("couldn't get private key: %v", err)
54. 	}
55. 	signer, ok := cryptoPrivKey.(crypto.Signer)
56. 	if !ok {
57. 		return nil, fmt.Errorf("private key is invalid type")
58. 	}
59. 	uid := packet.NewUserId(name, comment, email)
60. 	if uid == nil {
61. 		return nil, errors.InvalidArgumentError("invalid characters in user ID")
62. 	}
63. 	ecdsaPubKey, ok := ck.Public.(*ecdsa.PublicKey)
64. 	if !ok {
65. 		// TODO: handle ed25519 keys
66. 		return nil, fmt.Errorf("not an ECDSA key")
67. 	}
68. 	pub := packet.NewECDSAPublicKey(now, ecdsaPubKey)
69. 	priv := packet.NewSignerPrivateKey(now, signer)
70. 	selfSignature := packet.Signature{
71. 		CreationTime: now,
72. 		SigType:      packet.SigTypePositiveCert,
73. 		// TODO: determine the key type
74. 		PubKeyAlgo:  packet.PubKeyAlgoECDSA,
75. 		Hash:        crypto.SHA256,
76. 		IssuerKeyId: &pub.KeyId,
77. 		FlagsValid:  true,
78. 		FlagSign:    true,
79. 		FlagCertify: true,
80. 	}
81. 	err = selfSignature.SignUserId(uid.Id, pub, priv, nil)
82. 	if err != nil {
83. 		return nil, fmt.Errorf("couldn't sign user ID: %v", err)
84. 	}
85. 	return &openpgp.Entity{
86. 		PrimaryKey: pub,
87. 		PrivateKey: priv,
88. 		Identities: map[string]*openpgp.Identity{
89. 			uid.Id: {
90. 				Name:          uid.Name,
91. 				UserId:        uid,
92. 				SelfSignature: &selfSignature,
93. 			},
94. 		},
95. 	}, nil
96. }
97. 
98. // synthesizeEntities returns an array of signing and decrypting Entities for
99. // k's cryptographic keys.
100. // Because OpenPGP entities must be self-signed, this function needs a physical
101. // touch on the yubikey for slots with touch policies that require it.
102. func (k *SecurityKey) synthesizeEntities(name, email string) ([]Entity,
103. 	[]Entity, error) {
104. 	now := time.Now()
105. 	var signing, decrypting []Entity
106. 	for _, sk := range k.SigningKeys() {
107. 		e, err := k.synthesizeEntity(&sk.CryptoKey, now, name, email,
108. 			fmt.Sprintf("piv-agent signing key; touch-policy %s",
109. 				touchStringMap[sk.CryptoKey.SlotSpec.TouchPolicy]))
110. 		if err != nil {
111. 			return nil, nil, fmt.Errorf("couldn't synthesize entity: %v", err)
112. 		}
113. 		signing = append(signing, Entity{Entity: *e, CryptoKey: sk.CryptoKey})
114. 	}
115. 	for _, dk := range k.DecryptingKeys() {
116. 		e, err := k.synthesizeEntity(&dk.CryptoKey, now, name, email,
117. 			fmt.Sprintf("piv-agent decrypting key; touch-policy %s",
118. 				touchStringMap[dk.CryptoKey.SlotSpec.TouchPolicy]))
119. 		if err != nil {
120. 			return nil, nil, fmt.Errorf("couldn't synthesize entity: %v", err)
121. 		}
122. 		decrypting = append(decrypting, Entity{Entity: *e, CryptoKey: dk.CryptoKey})
123. 	}
124. 	return signing, decrypting, nil
125. }
126. 
127. func (k *SecurityKey) armorEntity(e *openpgp.Entity,
128. 	t piv.TouchPolicy) (string, error) {
129. 	buf := bytes.Buffer{}
130. 	w, err := armor.Encode(&buf, openpgp.PublicKeyType,
131. 		map[string]string{
132. 			"Comment": fmt.Sprintf("%v #%v, touch policy: %s",
133. 				k.card, k.serial, touchStringMap[t]),
134. 		})
135. 	if err != nil {
136. 		return "", fmt.Errorf("couldn't get PGP public key armorer: %w", err)
137. 	}
138. 	err = e.Serialize(w)
139. 	if err != nil {
140. 		return "", fmt.Errorf("couldn't serialize PGP public key: %w", err)
141. 	}
142. 	err = w.Close()
143. 	if err != nil {
144. 		return "", fmt.Errorf("couldn't close pgp writer: %w", err)
145. 	}
146. 	return buf.String(), nil
147. }
148. 
149. // StringsGPG returns an array of commonly formatted GPG keys as strings.
150. func (k *SecurityKey) StringsGPG(name, email string) ([]string, error) {
151. 	var ss []string
152. 	signing, decrypting, err := k.synthesizeEntities(name, email)
153. 	if err != nil {
154. 		return nil, fmt.Errorf("couldn't synthesize entities: %v", err)
155. 	}
156. 	ss = append(ss, "\nSigning GPG Keys:")
157. 	for _, key := range signing {
158. 		s, err := k.armorEntity(&key.Entity, key.SlotSpec.TouchPolicy)
159. 		if err != nil {
160. 			return nil, fmt.Errorf("couldn't armor entity: %v", err)
161. 		}
162. 		ss = append(ss, s)
163. 	}
164. 	ss = append(ss, "\nDecrypting GPG Keys:")
165. 	for _, key := range decrypting {
166. 		s, err := k.armorEntity(&key.Entity, key.SlotSpec.TouchPolicy)
167. 		if err != nil {
168. 			return nil, fmt.Errorf("couldn't armor entity: %v", err)
169. 		}
170. 		ss = append(ss, s)
171. 	}
172. 	return ss, nil
173. }
174.

