199. 				switch Event(e) {
200. 				case setkey:
201. 					// SETKEY has a single argument: a keygrip indicating the key which
202. 					// will be used for subsequent decrypting operations
203. 					keygrips, err = hexDecode(assuan.data...)
204. 					if err != nil {
