293. func (assuan *Assuan) havekey(rw io.ReadWriter, ks []KeyService) error {
294. 	var err error
295. 	var keyFound bool
296. 	var keygrips [][]byte
297. 	// HAVEKEY arguments are either:
298. 	// * a list of keygrips; or
299. 	// * --list=1000
300. 	// if _any_ key is available, we return OK, otherwise No_Secret_Key.
301. 	// handle --list
302. 	if bytes.HasPrefix(assuan.data[0], []byte("--list")) {
303. 		var grips []byte
304. 		grips, err = allKeygrips(ks)
305. 		if err != nil {
306. 			_, _ = io.WriteString(rw, "ERR 1 couldn't list keygrips\n")
307. 			return err
308. 		}
309. 		// apply buggy libgcrypt encoding
310. 		_, err = io.WriteString(rw, fmt.Sprintf("D %s\nOK\n",
311. 			PercentEncodeSExp(grips)))
312. 		return err
313. 	}
314. 	// handle list of keygrips
315. 	keygrips, err = hexDecode(assuan.data...)
316. 	if err != nil {
317. 		return fmt.Errorf("couldn't decode keygrips: %v", err)
318. 	}
319. 	keyFound, _, err = haveKey(ks, keygrips)
320. 	if err != nil {
321. 		_, _ = io.WriteString(rw, "ERR 1 couldn't check for keygrip\n")
322. 		return err
323. 	}
324. 	if keyFound {
325. 		_, err = io.WriteString(rw, "OK\n")
326. 	} else {
327. 		_, err = io.WriteString(rw, "No_Secret_Key\n")
328. 	}
329. 	return err
330. }
