332. // doKeyinfo checks for key availability by keygrip, writing the result to rw.
333. func doKeyinfo(rw io.ReadWriter, data [][]byte, ks []KeyService) error {
334. 	// KEYINFO arguments are a list of keygrips
335. 	// if _any_ key is available, we return info, otherwise
336. 	// No_Secret_Key.
337. 	keygrips, err := hexDecode(data...)
338. 	if err != nil {
339. 		return fmt.Errorf("couldn't decode keygrips: %v", err)
340. 	}
341. 	keyFound, keygrip, err := haveKey(ks, keygrips)
