 // Package assuan implements an libgcrypt Assuan protocol server.
 package assuan

 //go:generate mockgen -source=assuan.go -destination=../mock/mock_assuan.go -package=mock

 import (
 	"bufio"
 	"bytes"
 	"crypto"
 	"encoding/hex"
 	"fmt"
 	"io"
