27. 	rawPIN, err := terminal.ReadPassword(int(os.Stdin.Fd()))
28. 	fmt.Println()
29. 	if err != nil {
30. 		return 0, fmt.Errorf("couldn't read PIN/PUK: %w", err)
31. 	}
