178. 					}
179. 					_, err = rw.Write(signature)
180. 					if err != nil {
181. 						return fmt.Errorf("couldn't write signature: %v", err)
182. 					}
183. 					_, err = io.WriteString(rw, "\n")
184. 					if err != nil {
185. 						return fmt.Errorf("couldn't write newline: %v", err)
186. 					}
187. 					_, err = io.WriteString(rw, "OK\n")
