286. func (assuan *Assuan) reset() {
287. 	assuan.signer = nil
288. 	assuan.decrypter = nil
289. 	assuan.hashAlgo = 0
290. 	assuan.hash = []byte{}
291. }
292. 
293. func (assuan *Assuan) havekey(rw io.ReadWriter, ks []KeyService) error {
294. 	var err error
295. 	var keyFound bool
296. 	var keygrips [][]byte
297. 	// HAVEKEY arguments are either:
298. 	// * a list of keygrips; or
299. 	// * --list=1000
300. 	// if _any_ key is available, we return OK, otherwise No_Secret_Key.
301. 	// handle --list
302. 	if bytes.HasPrefix(assuan.data[0], []byte("--list")) {
303. 		var grips []byte
304. 		grips, err = allKeygrips(ks)
305. 		if err != nil {
306. 			_, _ = io.WriteString(rw, "ERR 1 couldn't list keygrips\n")
307. 			return err
308. 		}
309. 		// apply buggy libgcrypt encoding
310. 		_, err = io.WriteString(rw, fmt.Sprintf("D %s\nOK\n",
311. 			PercentEncodeSExp(grips)))
312. 		return err
313. 	}
314. 	// handle list of keygrips
315. 	keygrips, err = hexDecode(assuan.data...)
316. 	if err != nil {
317. 		return fmt.Errorf("couldn't decode keygrips: %v", err)
318. 	}
319. 	keyFound, _, err = haveKey(ks, keygrips)
320. 	if err != nil {
321. 		_, _ = io.WriteString(rw, "ERR 1 couldn't check for keygrip\n")
322. 		return err
323. 	}
324. 	if keyFound {
325. 		_, err = io.WriteString(rw, "OK\n")
326. 	} else {
327. 		_, err = io.WriteString(rw, "No_Secret_Key\n")
328. 	}
329. 	return err
330. }
331. 
332. // doKeyinfo checks for key availability by keygrip, writing the result to rw.
333. func doKeyinfo(rw io.ReadWriter, data [][]byte, ks []KeyService) error {
334. 	// KEYINFO arguments are a list of keygrips
335. 	// if _any_ key is available, we return info, otherwise
336. 	// No_Secret_Key.
337. 	keygrips, err := hexDecode(data...)
338. 	if err != nil {
339. 		return fmt.Errorf("couldn't decode keygrips: %v", err)
340. 	}
341. 	keyFound, keygrip, err := haveKey(ks, keygrips)
342. 	if err != nil {
343. 		_, _ = io.WriteString(rw, "ERR 1 couldn't match keygrip\n")
344. 		return fmt.Errorf("couldn't match keygrip: %v", err)
345. 	}
346. 	if keyFound {
347. 		_, err = io.WriteString(rw,
348. 			fmt.Sprintf("S KEYINFO %s D - - - - - - -\nOK\n",
349. 				strings.ToUpper(hex.EncodeToString(keygrip))))
350. 		return err
351. 	}
352. 	_, err = io.WriteString(rw, "No_Secret_Key\n")
353. 	return err
354. }
355. 
356. // haveKey returns true if any of the keygrips refer to keys known locally, and
357. // false otherwise.
358. // It takes keygrips in raw byte format, so keygrip in hex-encoded form must
359. // first be decoded before being passed to this function. It returns the
360. // keygrip found.
361. func haveKey(ks []KeyService, keygrips [][]byte) (bool, []byte, error) {
362. 	var keyFound bool
363. 	var keygrip []byte
364. 	var err error
365. 	for _, k := range ks {
366. 		keyFound, keygrip, err = k.HaveKey(keygrips)
367. 		if err != nil {
368. 			return false, nil, fmt.Errorf("couldn't check %s keygrips: %v", k.Name(), err)
369. 		}
370. 		if keyFound {
371. 			return true, keygrip, nil
372. 		}
373. 	}
374. 	return false, nil, nil
375. }
376. 
377. // allKeygrips returns all keygrips available for any keyservice, concatenated
378. // into a single byte slice.
379. func allKeygrips(ks []KeyService) ([]byte, error) {
380. 	var grips []byte
381. 	for _, k := range ks {
